css:
.print-format .data-field {
	margin-top: 3px;
	margin-bottom: 3px;
}

.print-format .section-break h4 {
	font-size: 1em;
	font-weight: 600;
	padding-bottom: 4px;
	margin-bottom: 8px;
	border-bottom: 1px solid #171717;
}

.print-format .table-bordered {
	border: none;
}

.print-format .table-bordered > thead > tr > th,
.print-format .table-bordered > tbody > tr > td {
	border-left: none !important;
	border-right: none !important;
	border-top: none !important;
}

.print-format .table > thead > tr > th {
	background-color: transparent !important;
	border-bottom: 1.5px solid #171717 !important;
}

.print-format .table > tbody > tr > td {
	border-bottom: none !important;
}

.print-format .table > tbody > tr:nth-child(even) > td {
	background-color: #f3f3f3 !important;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}
